function cleanStr(str) {
  if (!str) return '';
  return str
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

/**
 * Autenticación oficial:
 * 1. OPCIÓN 1: Primer nombre y primer apellido (usuario y contraseña) habilitado para TODOS los 4,027 estudiantes.
 * 2. OPCIÓN 2: DNI como contraseña o usuario.
 */
function authenticateParticipant(usernameInput, passwordInput) {
  if (!usernameInput || !passwordInput) {
    return {
      success: false,
      message: 'Por favor ingresa tu usuario y contraseña.'
    };
  }

  const uClean = cleanStr(usernameInput);
  const pClean = cleanStr(passwordInput);

  if (uClean.length < 2) {
    return {
      success: false,
      message: 'El usuario debe tener al menos 2 caracteres.'
    };
  }

  const match = STUDENTS_DATABASE.find(st => {
    const dniClean = st.dni ? cleanStr(st.dni) : '';
    const pRecord = st.p ? cleanStr(st.p) : '';
    const uRecord = cleanStr(st.u);
    const nRecord = cleanStr(st.n);
    const eRecord = cleanStr(st.e);

    // Contraseña válida:
    // A) Primer nombre y primer apellido (uRecord) -> OPCIÓN 1 PARA TODOS
    // B) Nombre completo (nRecord)
    // C) Contraseña guardada en pRecord (DNI o nombre)
    // D) DNI individual registrado -> OPCIÓN 2
    // E) Cualquier variante en palabras clave (st.k)
    const matchesPassword = (pClean === uRecord) || 
                            (pClean === nRecord) || 
                            (pRecord && pClean === pRecord) || 
                            (dniClean && pClean === dniClean) || 
                            (st.k && st.k.some(kw => cleanStr(kw) === pClean));

    // Usuario válido:
    // A) Primer nombre y primer apellido (uRecord)
    // B) Nombre completo registrado (nRecord)
    // C) DNI registrado (dniClean)
    // D) Email (eRecord)
    // E) Cualquier variante de nombre o apellido en palabras clave (st.k)
    const matchesUser = (uClean === uRecord) || 
                        (uClean === nRecord) || 
                        (dniClean && uClean === dniClean) || 
                        (uClean === eRecord) || 
                        (st.k && st.k.some(kw => cleanStr(kw) === uClean));

    // Regla 1: Coincidencia de usuario y contraseña
    if (matchesUser && matchesPassword) return true;

    // Regla 2: Opción 2 con DNI (ingresó DNI en ambos campos)
    if (dniClean && uClean === dniClean && pClean === dniClean) return true;

    // Regla 3: Opción 1 con nombre (ingresó su nombre en ambos campos)
    if ((uClean === uRecord || uClean === nRecord) && uClean === pClean) return true;

    // Regla 4: Opción 2 con DNI (ingresó DNI como contraseña y el nombre coincide parcialmente)
    if (dniClean && pClean === dniClean) {
      if (st.k && st.k.some(kw => cleanStr(kw).includes(uClean) || uClean.includes(cleanStr(kw)))) return true;
    }

    // Regla 5: Opción 1 con nombre (ingresó nombre como contraseña y el usuario coincide parcialmente)
    if (pClean === uRecord || pClean === nRecord) {
      if (st.k && st.k.some(kw => cleanStr(kw).includes(uClean) || uClean.includes(cleanStr(kw)))) return true;
    }

    return false;
  });

  if (match) {
    const studentCourses = match.courses || ['bootcamp-portugues-cero'];
    const studentRole = match.role || 'Estudiante Inscrito · Portugués Desde Cero';

    return {
      success: true,
      student: {
        name: match.n,
        shortName: match.u,
        email: match.e,
        dni: match.dni || null,
        role: studentRole,
        passportNo: 'PM-' + Math.abs(match.n.split('').reduce((a, b) => ((a << 5) - a) + b.charCodeAt(0), 0) % 9000 + 1000),
        allowedCourses: studentCourses
      }
    };
  }

  return {
    success: false,
    message: 'Usuario o contraseña no encontrados. Puedes ingresar con: 1) Tu primer nombre y primer apellido, o 2) Tu DNI si te registraste con él.'
  };
}

if (typeof window !== 'undefined') {
  window.STUDENTS_DATABASE = STUDENTS_DATABASE;
  window.authenticateParticipant = authenticateParticipant;
}

if (typeof module !== 'undefined') {
  module.exports = { STUDENTS_DATABASE, authenticateParticipant };
}
